    pub(crate) fn decode<R: MemRead>(
        &mut self,
        cx: &mut Context<'_>,
        body: &mut R,
    ) -> Poll<Result<Frame<Bytes>, io::Error>> {
        trace!("decode; state={:?}", self.kind);
        match self.kind {
            Length(ref mut remaining) => {
                if *remaining == 0 {
                    Poll::Ready(Ok(Frame::data(Bytes::new())))
                } else {
                    let to_read = *remaining as usize;
                    let buf = ready!(body.read_mem(cx, to_read))?;
                    let num = buf.as_ref().len() as u64;
                    if num > *remaining {
                        *remaining = 0;
                    } else if num == 0 {
                        return Poll::Ready(Err(io::Error::new(
                            io::ErrorKind::UnexpectedEof,
                            IncompleteBody,
                        )));
                    } else {
                        *remaining -= num;
                    }
                    Poll::Ready(Ok(Frame::data(buf.freeze())))
                }
            }
            Eof(ref mut is_eof) => {
                let buf = ready!(body.read_mem(cx, 1))?;
                let num = buf.as_ref().len();
                if num == 0 {
                    *is_eof = true;
                    Poll::Ready(Ok(Frame::data(Bytes::new())))
                } else {
                    Poll::Ready(Ok(Frame::data(buf.freeze())))
                }
            }
            Chunked {
                ref mut state,
                ref mut chunk_len,
                ref mut extensions_cnt,
                ref mut trailers_buf,
                ref mut trailers_cnt,
                ref mut h1_max_headers,
                ref mut h1_max_header_size,
            } => {
                loop {
                    trace!("state; state={:?}", *state);
                    let next = match *state {
                        ChunkedState::Start => ChunkedState::read_start(cx, body)?,
                        ChunkedState::Size => ChunkedState::read_size(cx, body)?,
                        ChunkedState::SizeLws => ChunkedState::read_size_lws(cx, body)?,
                        ChunkedState::Extension => ChunkedState::read_extension(cx, body)?,
                        ChunkedState::SizeLf => ChunkedState::read_size_lf(cx, body, *chunk_len)?,
                        ChunkedState::Body => ChunkedState::read_body(cx, body, chunk_len)?,
                        ChunkedState::BodyCr => ChunkedState::read_body_cr(cx, body)?,
                        ChunkedState::BodyLf => ChunkedState::read_body_lf(cx, body)?,
                        ChunkedState::Trailer => ChunkedState::read_trailer(cx, body)?,
                        ChunkedState::TrailerLf => ChunkedState::read_trailer_lf(cx, body)?,
                        ChunkedState::EndCr => ChunkedState::read_end_cr(cx, body)?,
                        ChunkedState::EndLf => ChunkedState::read_end_lf(cx, body)?,
                        ChunkedState::End => {
                            // End state: return empty frame to signal end of body
                            return Poll::Ready(Ok(Frame::data(Bytes::new())));
                        }
                    };
                    *state = next;
                }
            }
        }
