// walkSchema walks the schema tree and applies the given function to each schema.
func walkSchema(schema Schema, fn func(Schema) Schema) Schema {
	schema = fn(schema)

	switch s := schema.(type) {
	case *RecordSchema:
		for i, field := range s.Fields() {
			s.fields[i].Type = walkSchema(field.Type, fn)
		}
	case *ArraySchema:
		s.items = walkSchema(s.items, fn)
	case *MapSchema:
		s.values = walkSchema(s.values, fn)
	case *UnionSchema:
		for i, t := range s.types {
			s.types[i] = walkSchema(t, fn)
		}
	case *FixedSchema:
	case *EnumSchema:
	case *RefSchema:
		// Don't walk into references
	}

	return schema
}
