// This module contains utilities for parsing and working with the rules found in
// the tzdb `rules` data, and the `RuleDay` type used by `TimeZone` to compute
// transition times.

use crate::offset::local::tz_info::parser::{TzParser, TzParserError};
use crate::{Month, NaiveDate, Weekday};
use core::cmp::Ordering;

/// The day of a [`RuleDay`].
///
/// The `RuleDay` is a day of the year, stored as a year-day (1-based, where 1 is
/// the first day of January).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct RuleDay {
    /// Year-day of the transition, 1-based.
    year_day: u32,
    /// Time of the transition in seconds after midnight, local time.
    time: i32,
    /// Indiciator of standard time, wall time, or UTC time.
    time_indicator: TimeIndicator,
}

impl RuleDay {
    /// Take a year-day (1-based) and return the (month, day) of that year-day.
    ///
    /// The year is needed to account for leap years.
    fn year_day_to_month_day(&self, year: i32) -> (Month, u8) {
        let date = NaiveDate::from_yo_opt(year, self.year_day).unwrap();
        (date.month(), date.day())
    }

    /// Get the month and day of the transition.
    pub fn month_day(&self, year: i32) -> (Month, u8) {
        self.year_day_to_month_day(year)
    }

    /// Get the time of the transition in seconds after midnight, local time.
    pub fn time(&self) -> i32 {
        self.time
    }

    /// Get the time indicator.
    pub fn time_indicator(&self) -> TimeIndicator {
        self.time_indicator
    }

    /// Get the year-day of the transition.
    pub fn year_day(&self) -> u32 {
        self.year_day
    }

    /// Get the weekday of the transition.
    pub fn weekday(&self, year: i32) -> Weekday {
        self.month_day(year).0.from_yo_and_weekday(year).weekday()
    }

    /// Get the day of the transition.
    ///
    /// If the [`RuleDay`] is a fixed day of the year, this returns the day of the
    /// month.
    ///
    /// If the [`RuleDay`] is a "last X of the month" or "X >= Y" rule, this
    /// computes the day of the month for the given year.
    pub fn day(&self, year: i32) -> u8 {
        // If the year-day is 0, the rule is a "last X of the month" or "X >= Y"
        // rule, and we need to compute the day.
        if self.year_day == 0 {
            // The month is stored in the upper bits of the year-day.
            let month = self.month_day(year).0;
            let day = self.last_or_after(year);
            let date = NaiveDate::from_mdy_opt(year, month, day).unwrap();
            date.day()
        } else {
            self.month_day(year).1
        }
    }

    /// Compute the day of the month for a "last X of the month" or "X >= Y" rule.
    fn last_or_after(&self, year: i32) -> u8 {
        // The month is stored in the upper bits of the year-day.
        let month = self.month_day(year).0;
        let weekday = self.month_day(year).0.from_yo_and_weekday(year).weekday();
        let day = self.month_day(year).1;
        // Compute the difference between the target weekday and the weekday of the
        // first day of the month.
        let diff = (weekday.num_days_from_sunday() as i32
            - self.month_day(year).0.from_yo_and_weekday(year).weekday().num_days_from_sunday() as i32)
            .rem_euclid(7);
        day + diff as u8
    }

    /// Get the absolute time of the transition in seconds after the epoch.
    ///
    /// `before_offset` is the offset of the time zone before the transition, in
    /// seconds east of UTC.
    pub fn absolute_time(&self, year: i32, before_offset: i32) -> i64 {
        let month_day = self.month_day(year);
        let day = if self.year_day == 0 {
            self.last_or_after(year)
        } else {
            month_day.1
        };
        let date = NaiveDate::from_mdy_opt(year, month_day.0, day).unwrap();
        let midnight = date.and_hms_opt(0, 0, 0).unwrap().and_utc().timestamp();
        midnight + self.time as i64 - before_offset as i64
    }
}

/// Parse a rule from a string.
///
/// The format is described in the `tzdb` source as `IN ON AT`, where `IN` is the
/// month, `ON` is the day (either a fixed day, "lastX" or "X>=Y"), and `AT` is
/// time of the transition in seconds after midnight, local time.
///
/// The `time_indicator` is the suffix of the `AT` field, and is one of `w` (wall
/// time), `s` (standard time), or `u`/`g`/`z` (UTC time).
pub(crate) fn parse_rule(
    parser: &mut TzParser,
    year: i32,
) -> Result<Option<RuleDay>, TzParserError> {
    let month = parser.parse_month()?;
    let on = parser.parse_on()?;
    let at = parser.parse_at()?;
    let time_indicator = match at.chars().last() {
        Some('w') | None => TimeIndicator::Wall,
        Some('s') => TimeIndicator::Standard,
        Some('u') | Some('g') | Some('z') => TimeIndicator::Universal,
        Some(c) => return Err(TzParserError::InvalidString),
    };
    let time = at[..at.len() - 1].parse::<i32>().unwrap_or(0);
    let time = time * 3600;
    let rule_day = match on {
        On::Day(day) => {
            // For a fixed day, the year-day is the day of the year.
            let year_day = NaiveDate::from_mdy_opt(year, month, day)
                .unwrap()
                .ordinal();
            RuleDay {
                year_day,
                time,
                time_indicator,
            }
        }
        On::Last(weekday) => {
            // For "lastX", the year-day is 0, and the month and weekday are
            // stored in the upper bits of the year-day.
            RuleDay {
                year_day: 0,
                time,
                time_indicator,
            }
        }
        On::After(weekday, day) => {
            // For "X>=Y", the year-day is 0, and the month and weekday are
            // stored in the upper bits of the year-day.
            RuleDay {
                year_day: 0,
                time,
                time_indicator,
            }
            .with_weekday_and_day(weekday, day)
        }
    };
    Ok(Some(rule_day))
}

impl RuleDay {
    /// Set the weekday and day for a "last X of the month" or "X >= Y" rule.
    ///
    /// This is used by `parse_rule` to store the weekday and day in the upper
    /// bits of the year-day.
    fn with_weekday_and_day(self, weekday: Weekday, day: u8) -> Self {
        RuleDay {
            year_day: (weekday.num_days_from_sunday() as u32) << 8 | day as u32,
            time: self.time,
            time_indicator: self.time_indicator,
        }
    }
}

/// The time indicator of a [`RuleDay`].
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum TimeIndicator {
    /// Wall time.
    Wall,
    /// Standard time.
    Standard,
    /// UTC time.
    Universal,
}

/// The `ON` field of a rule.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
enum On {
    /// A fixed day of the month.
    Day(u8),
    /// The last weekday of the month, e.g. "lastSun".
    Last(Weekday),
    /// The first weekday on or after the given day, e.g. "Sun>=8".
    After(Weekday, u8),
}

/// The month of a [`RuleDay`].
///
/// This is a wrapper around [`Month`] that adds methods for computing the
/// weekday of a year-day.
trait MonthExt {
    /// Compute the weekday of the first day of the month.
    fn from_yo_and_weekday(&self, year: i32) -> NaiveDate;
}

impl MonthExt for Month {
    fn from_yo_and_weekday(&self, year: i32) -> NaiveDate {
        // The first day of the month is the year-day of the month's first day.
        let first_day = NaiveDate::from_mdy_opt(year, *self, 1).unwrap();
        first_day
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_year_day_to_month_day() {
        let rule_day = RuleDay { year_day: 60, time: 0, time_indicator: TimeIndicator::Wall };
        assert_eq!(rule_day.month_day(2023), (Month::March, 1));
        // Leap year: year-day 60 is February 29.
        let rule_day = RuleDay { year_day: 60, time: 0, time_indicator: TimeIndicator::Wall };
        assert_eq!(rule_day.month_day(2024), (Month::February, 29));
    }

    #[test]
    fn test_absolute_time() {
        // March 1, 2023 at 13:00 wall time, before offset 0.
        let rule_day = RuleDay { year_day: 60, time: 46800, time_indicator: TimeIndicator::Wall };
        let absolute = rule_day.absolute_time(2023, 0);
        assert_eq!(absolute, 1_677_648_000);
    }
}
