 /// Parse a rule from a string.
 ///
 /// The format is described in the `tzdb` source as `IN ON AT`, where `IN` is the
 /// month, `ON` is the day (either a fixed day, "lastX" or "X>=Y"), and `AT` is
 /// time of the transition in seconds after midnight, local time.
 ///
 /// The `time_indicator` is the suffix of the `AT` field, and is one of `w` (wall
 /// time), `s` (standard time), or `u`/`g`/`z` (UTC time).
 pub(crate) fn parse_rule(
     parser: &mut TzParser,
     year: i32,
 ) -> Result<Option<RuleDay>, TzParserError> {
     let month = parser.parse_month()?;
     let on = parser.parse_on()?;
     let at = parser.parse_at()?;
     let time_indicator = match at.chars().last() {
         Some('w') | None => TimeIndicator::Wall,
         Some('s') => TimeIndicator::Standard,
         Some('u') | Some('g') | Some('z') => TimeIndicator::Universal,
         Some(c) => return Err(TzParserError::InvalidString),
     };
     let time = at[..at.len() - 1].parse::<i32>().unwrap_or(0);
     let time = time * 3600;
     let rule_day = match on {
         On::Day(day) => {
             // For a fixed day, the year-day is the day of the year.
             let year_day = NaiveDate::from_mdy_opt(year, month, day)
                 .unwrap()
                 .ordinal();
             RuleDay {
                 year_day,
                 time,
                 time_indicator,
             }
         }
         On::Last(weekday) => {
             // For "lastX", the year-day is 0, and the month and weekday are
             // stored in the upper bits of the year-day.
             RuleDay {
                 year_day: 0,
                 time,
                 time_indicator,
             }
         }
         On::After(weekday, day) => {
             // For "X>=Y", the year-day is 0, and the month and weekday are
             // stored in the upper bits of the year-day.
             RuleDay {
                 year_day: 0,
                 time,
                 time_indicator,
             }
             .with_weekday_and_day(weekday, day)
         }
     };
     Ok(Some(rule_day))
 }

 impl RuleDay {
     /// Set the weekday and day for a "last X of the month" or "X >= Y" rule.
     ///
     /// This is used by `parse_rule` to store the weekday and day in the upper
     /// bits of the year-day.
     fn with_weekday_and_day(self, weekday: Weekday, day: u8) -> Self {
         RuleDay {
             year_day: (weekday.num_days_from_sunday() as u32) << 8 | day as u32,
             time: self.time,
             time_indicator: self.time_indicator,
         }
     }
 }

 /// The time indicator of a [`RuleDay`].
 #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
 pub enum TimeIndicator {
     /// Wall time.
     Wall,
     /// Standard time.
     Standard,
     /// UTC time.
     Universal,
 }

 /// The `ON` field of a rule.
 #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
 enum On {
     /// A fixed day of the month.
     Day(u8),
     /// The last weekday of the month, e.g. "lastSun".
     Last(Weekday),
     /// The first weekday on or after the given day, e.g. "Sun>=8".
     After(Weekday, u8),
 }

 /// The month of a [`RuleDay`].
 ///
 /// This is a wrapper around [`Month`] that adds methods for computing the
 /// weekday of a year-day.
 trait MonthExt {
     /// Compute the weekday of the first day of the month.
     fn from_yo_and_weekday(&self, year: i32) -> NaiveDate;
 }

 impl MonthExt for Month {
     fn from_yo_and_weekday(&self, year: i32) -> NaiveDate {
         // The first day of the month is the year-day of the month's first day.
         let first_day = NaiveDate::from_mdy_opt(year, *self, 1).unwrap();
         first_day
     }
 }

